WITH metrics AS (SELECT id, device_code, reading_ts, humidity, pressure, DENSE_RANK() OVER w_running AS humidity_dense_rank, CUME_DIST() OVER w_running_2 AS humidity_cume_dist FROM device_readings WINDOW w_running AS (PARTITION BY device_code ORDER BY humidity DESC), w_running_2 AS (PARTITION BY device_code ORDER BY humidity DESC NULLS FIRST)) SELECT id, device_code, reading_ts, humidity, humidity_dense_rank, humidity_cume_dist, CASE WHEN device_code RLIKE '^(DV-02|DV-01)$' THEN 'GROUP_B' ELSE 'CORE' END AS device_code_zone FROM metrics ORDER BY reading_ts DESC NULLS LAST
